contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: send some amount to c.go and check invariants
    function run(uint64 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // allow sending Ether from this test contract to c.go by using `amount` param
        // ensure this contract has at least `amount` balance when making the call
        require(address(this).balance >= amount, "insufficient balance to send");

        // read owner and c balance before the call
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balBefore = address(c).balance;

        // perform the state-changing call on c, capturing whether it reverted
        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read owner and balance after the call
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint256 balAfter = address(c).balance;

        // General rule: owner does not change and C's balance is zero after go
        assert(ownerBefore == ownerAfter && balAfter == 0);
    }

    // receive to accept Ether forwarded back to this test contract
    receive() external payable {}
}

